    },
    {
      "path": "training/original-docs/PIXEL-ART-ASSETS.md",
      "start": 11,
      "end": 15
    }
  ],
  "poc": {
    "kind": "visual-review-fixture",
    "procedure": [
      "Draw a 16x16 key with a ring hole, shaft and two teeth; render mask and colored views on three backgrounds.",
      "Create a negative example by filling the hole and merging the teeth."
    ],
    "acceptance": [
      "Record native-scale contact sheets and explicit pass/fail for hole, shaft and both teeth.",
      "Negative example fails the landmark checklist; aesthetic review remains separate."
    ]
  }
